/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
public class METInventTransferTableExt extends common
{
}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    if(this.InventTransferTable)
    {
        super();
    }
}

    /// <summary>
    /// initialise variables
    /// </summary>
    public void initValue()
    {
        InventParameters    inventParameters = InventParameters::find();

        super();

        this.AllowBackorder = inventParameters.METAllowBackorder;

    }

    /// <summary>
    /// Are backorders allowed on a Transfer order, find by route Id
    /// </summary>
    /// <param name = "_pickingRouteId">Route Id</param>
    /// <returns>True/false</returns>
    public static boolean isAllowBackorderRouteId(WMSPickingRouteID _pickingRouteId)
    {
        boolean allowed = false;
    
        WMSPickingRoute             pickingRoute;
        InventTransferTable         inventTransferTable;
        METInventTransferTableExt   inventTransferTableExt;

        while select firstonly pickingRouteID from pickingRoute
            where   pickingRoute.pickingRouteID == _pickingRouteId

            exists  join inventTransferTable
            where   inventTransferTable.TransferId == pickingRoute.transRefId

            exists  join inventTransferTableExt
            where   inventTransferTableExt.InventTransferTable   == inventTransferTable.RecId
            &&      inventTransferTableExt.AllowBackorder        == NoYes::Yes
        {
            allowed = true;
        }

        return allowed;
    }

    /// <summary>
    /// get auto extract value
    /// </summary>
    /// <param name = "_metInventLocationIdFrom">from warehouse</param>
    /// <param name = "_metInventLocationIdTo">to warehouse</param>
    /// <returns>True/false</returns>
    public static METAutoExtract metIsAutoExtract(InventLocationIdFrom _metInventLocationIdFrom, InventLocationIdTo _metInventLocationIdTo)
    {
        METAutoExtract metAutoExtract = NoYes::No;

        if(InventLocation::metGetAutoExtract(_metInventLocationIdFrom) && InventLocation::metGetAutoExtract(_metInventLocationIdTo))
        {
            metAutoExtract = NoYes::yes;
        }

        return metAutoExtract;
    }

/// <summary>
/// Set Extraction status
/// </summary>
 public void  setExtractionStatus()
{
    this.OrderExtractStatus = this.AutoExtract == NoYes::Yes ? METOrderExtractStatus::ReadyForExtract : METOrderExtractStatus::Open;
}

    /// <summary>
    /// Update Extract status
    /// </summary>
    /// <param name = "_transferId">Transfer order id</param>
    public static void UpdateExtractionStatus(InventTransferId  _transferId)
    {
        InventTransferTable         inventTransferTable;
        METInventTransferTableExt   inventTransferTableExt;
        InventTransferLine          inventTransferLine;
        METInventTransferLine       metInventTransferLine;

        select firstonly RecId from metInventTransferLine
            exists join inventTransferLine 
            where inventTransferLine.TransferId == _transferId
            && metInventTransferLine.InventTransferLine == inventTransferLine.RecId
            && metInventTransferLine.OrderExtractStatus == METOrderExtractStatus::Open;
      
        select firstonly forupdate inventTransferTableExt
            join RecId from inventTransferTable
            where inventTransferTable.RecId == inventTransferTableExt.InventTransferTable
            && inventTransferTable.TransferId == _transferId;

        if (inventTransferTableExt)
        {
            ttsbegin;
            inventTransferTableExt.OrderExtractStatus = metInventTransferLine.RecId ? METOrderExtractStatus::Open : METOrderExtractStatus::Extracted;
            inventTransferTableExt.update();
            ttscommit;
        }
  
    }

    /// <summary>
    /// CB715_TransferOrderExtract
    /// </summary>
    /// <param name = "_transferId">
    /// Transfer order ID
    /// </param>
    /// <param name = "_pickingRouteId">
    /// Picking route ID
    /// </param>
    public static void createExtractRecords(InventTransferId    _transferId,WMSPickingRouteID _pickingRouteId)
    {
        METTransferOrderExtractPickingRouteTable        pickingRouteTable;
        LogisticsPostalAddress                          postalAddress;
        InventLocation                                  shippingLocation;
        InventTransferTable                             transferTable;
        METInventTransferTableExt                       metTransferTable;
        METRouteTable                                   routeTable;        
        WMSOrderTrans                                   orderTrans;
        InventTransferLine                              transferLine;
        METInventTransferLine                           metTransferLine;

        transferTable           = InventTransferTable::find(_transferId);
        metTransferTable        = transferTable.metInventTransferTableExt();
        shippingLocation        = InventLocation::find(transferTable.InventLocationIdFrom);
        routeTable              = METRouteTable::findByRouteIdentifier(metTransferTable.RouteIdentifier);
        postalAddress           = LogisticsPostalAddress::findRecId(transferTable.FromPostalAddress);

        pickingRouteTable.clear();

        pickingRouteTable.DefaultShippingWarehouseId    = shippingLocation.InventLocationId;
        pickingRouteTable.DefaultShippingSiteId         = shippingLocation.InventSiteId;
        pickingRouteTable.OrderingCustomerAccountNumber = shippingLocation.metInventLocation().InternalCustomer;
        pickingRouteTable.OrderCreationDateTime         = transferTable.CreatedDateTime;
        pickingRouteTable.SalesOrderNumber              = _transferId;
        pickingRouteTable.RouteStopNum                  = metTransferTable.RouteStopNum;
        pickingRouteTable.Door                          = metTransferTable.Door;
        pickingRouteTable.OrderCutOffDay                = routeTable.OrderCutOffDay;
        pickingRouteTable.OrderCutOffTime               = routeTable.OrderCutOffTime;
        pickingRouteTable.DispatchDay                   = routeTable.DispatchDay;
        pickingRouteTable.DispatchTime                  = routeTable.DispatchTime;
        pickingRouteTable.StagingLane                   = metTransferTable.StagingLane;
        pickingRouteTable.OrderType                     = metTransferTable.CSDTOType;
        pickingRouteTable.DeliveryAddressStreetNumber   = postalAddress.StreetNumber;
        pickingRouteTable.DeliveryAddressStreet         = postalAddress.Street;
        pickingRouteTable.DeliveryAddressCity           = postalAddress.City;
        pickingRouteTable.DeliveryAddressState          = postalAddress.State;
        pickingRouteTable.DeliveryAddressZipCode        = postalAddress.ZipCode;
        pickingRouteTable.SalesOrderName                = shippingLocation.Name;
        pickingRouteTable.ConfirmationDocumentReference = _transferId + '-' + any2Str(transferTable.RecVersion);

        select sum(TotalWeight),sum(TotalVolume) from metTransferLine
            exists join transferLine
                where transferLine.RecId == metTransferLine.InventTransferLine
            exists join orderTrans
                where orderTrans.inventTransId == transferLine.InventTransId
                && orderTrans.routeId == _pickingRouteId;                

        pickingRouteTable.TotalNetVolume                = metTransferLine.TotalVolume;
        pickingRouteTable.TotalNetWeight                = metTransferLine.TotalWeight;
        pickingRouteTable.insert();
    }

    /// <summary>
    /// CB715_TransferOrderExtract
    /// </summary>
    /// <param name = "_transferId">
    /// Transfer order ID
    /// </param>
    /// <param name = "_pickingRouteId">
    /// Picking route ID
    /// </param>
    public static void createExtractTransRecords(InventTransferId    _transferId,WMSPickingRouteID _pickingRouteId)
    {
        RecordInsertList                                ril;
        METTransferOrderExtractOrderTransTable          extractTransRecord;
        WMSOrderTrans                                   orderTrans;
        InventTransferLine                              transferLine;
        InventDim                                       inventDim;
        InventSite                                      inventSite;        
        METInventTransferLine                           metTransferLine;

        ril = new RecordInsertList(tableNum(METTransferOrderExtractOrderTransTable));

        while select orderTrans
            where orderTrans.routeId == _pickingRouteId
        {
            extractTransRecord = null;

            extractTransRecord.SalesOrderNumber         = _pickingRouteId;
            extractTransRecord.ItemNumber               = orderTrans.itemId;
            extractTransRecord.ReservedQty              = orderTrans.qty;

            inventDim                                   = orderTrans.inventDim();
            inventSite                                  = inventDim.inventSite();

            extractTransRecord.MTCLegacyCode            = MetItemSiteSettingsSetup::find(orderTrans.itemId,inventSite.SiteId).MTCLegacyCode;           
            extractTransRecord.BondedWarehouse          = inventSite.METBondedWarehouse;
            extractTransRecord.SalesUnitSymbol          = orderTrans.unitId();
            extractTransRecord.PickEaches               = inventDim.inventLocation().metInventLocation().PickEaches;

            transferLine                                = InventTransferLine::findTransIdShip(orderTrans.inventTransId);
            extractTransRecord.SalesOrderLineStatus     = transferLine.RemainStatus;
            extractTransRecord.LineNum                  = transferLine.LineNum;

            metTransferLine                             = transferLine.metInventTransferLine();

            extractTransRecord.WHUOM                    = metTransferLine.WarehouseUnitId;
            extractTransRecord.Volume                   = metTransferLine.TOUnitVolume;
            extractTransRecord.Weight                   = metTransferLine.TOUnitWeight;
            extractTransRecord.ShipDate                 = transferLine.ShipDate;
            extractTransRecord.UnitPrice                = transferLine.UnitPrice;
            extractTransRecord.LineDescription          = transferLine.itemName();
            extractTransRecord.HMIMIndicator            = InventTable::find(extractTransRecord.ItemNumber).HMIMIndicator;

            ril.add(extractTransRecord);
        }

        ril.insertDatabase();        
    }
